function findTheLongestSubstring(s) {
  const vowelBit = new Map([['a', 1], ['e', 2], ['i', 4], ['o', 8], ['u', 16]]);
  const firstSeen = new Map([[0, -1]]);
  let mask = 0;
  let longest = 0;

  for (let i = 0; i < s.length; i++) {
    const bit = vowelBit.get(s[i]);
    if (bit !== undefined) {
      mask ^= bit;
    }
    if (!firstSeen.has(mask)) {
      firstSeen.set(mask, i);
    } else {
      longest = Math.max(longest, i - firstSeen.get(mask));
    }
  }
  return longest;
}

