function findTheLongestSubstring(s) {
  // Try every start, extend to the right while counting vowels, and test all five counts.
  let best = 0;
  for (let start = 0; start < s.length; start++) {
    const counts = new Map([['a', 0], ['e', 0], ['i', 0], ['o', 0], ['u', 0]]);
    for (let end = start; end < s.length; end++) {
      if (counts.has(s[end])) counts.set(s[end], counts.get(s[end]) + 1);
      if ([...counts.values()].every(c => c % 2 === 0)) best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

