function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabets = ['aeioubcd', 'aeiou', 'ab', 'eu', 'abcdefghijklmnopqrstuvwxyz', 'aaaaeb', 'xyz'];
  const alphabet = alphabets[pick(alphabets.length)];
  const n = size === 'large' ? 8000 + pick(2001) : 1 + pick(14);
  let s = '';
  for (let k = 0; k < n; k++) s += alphabet[pick(alphabet.length)];
  return [s];
}
